fn solve(n: i8) -> Vec<i8> {
    // Work with a wider integer type internally to avoid any overflow surprises.
    let n = n as i32;

    let full_weeks = n / 7;
    let r = n % 7;

    // Base days off from complete weeks
    let base = 2 * full_weeks;

    // For the remaining r days:
    // min extra = max(0, r - 5)
    // max extra = min(2, r)
    let min_extra = (r - 5).max(0);
    let max_extra = r.min(2);

    let min_days_off = base + min_extra;
    let max_days_off = base + max_extra;

    vec![min_days_off as i8, max_days_off as i8]
}